export function getArtworkUrl(info: { artworkUrl?: string | null, sourceName?: string | null, identifier?: string | null }): string {
  if (info.sourceName === 'youtube' && info.identifier) {
    // maxresdefault is often broken/missing for older videos (returns a 120x90 grey image),
    // but mqdefault.jpg (320x180) is always generated by YouTube and is perfectly sized for thumbnails.
    return `https://img.youtube.com/vi/${info.identifier}/mqdefault.jpg`;
  }
  return info.artworkUrl || '';
}
